      SUBROUTINE DEPIC2CC     CHARACTERIZES A SIMPLE ELEMENT OR ONE OF THE COMPONENTSC     OF A COMPOUND ELEMENT AS TO WHAT KIND OF MATRICES IT PRODUCESCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'CC     LOCAL VARIABLESC      INTEGER         TYT      EXTERNAL        IDATACC-------------------------------------------------------------------C      RMTX = .FALSE.      OMTX = .FALSE.      CFIT = .FALSE.      RSYM = .FALSE.      MPRN = .FALSE.C      IF (TYPE .GE. 82 .AND. TYPE .LE. 86) GO TO 5200      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800,5200,1000,     1       1100,1200,1300,1400,5200,1600,1700,1800,1900,2000,     2       5200,5200,5200,5200,2500,5200,2700,2800,2800,5200,     3       3100,5200,3300,3400,3500,3500,3700,3800,5200,5200,     4       4100,4200,4300,5200,4500,4600,4600,4600), TYPEC      GO TO 5200C  100 MPRN = .TRUE.      GO TO 5200C  200 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C  300 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C  400 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C  500 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C  600 MPRN = .TRUE.      GO TO 5200C  700 MPRN = .TRUE.      GO TO 5200C  800 IF (TYPE .NE. 6 .AND. TYPE .NE. 37) THEN        IF (TYPE .EQ. 2 .OR. TYPE .EQ. 4 .OR. TYPE .EQ. 28      1      .OR. TYPE .EQ. 29) THEN           NMR = NM4        ELSE IF (TYPE .EQ. 5) THEN           NMR = NM5        ELSE IF (TYPE .EQ. 8) THEN          NMR = NUM        ENDIF        IMIS = ISTOR(NMR)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100      ENDIF      RMTX = LFM .GE. 1      MPRN = .TRUE.      GO TO 5200C 1000 MPRN = .TRUE.      GO TO 5200C 1100 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C 1200 MPRN = .TRUE.      GO TO 5200C 1300 ID = INT(DATA(I+1))      OMTX = ID .EQ. 9 .AND. R1P      RMTX = ID .EQ. 11      MPRN = .TRUE.      GO TO 5200C 1400 IF (NDIF .EQ. 1 .AND. NUM + 1 .GT. NEL) GO TO 1410      IF (NDIF .EQ. -1 .AND. NUM - 1 .LE. 0) GO TO 1410      IPNOTY = ISTOR(NUM + NDIF)      NEXT = IDATA(IPNOTY)      IF (NEXT .EQ. TYPE) GO TO 1420 1410 RMTX = .TRUE. 1420 MPRN = .TRUE.      GO TO 5200C 1600 IF16 = INT(DATA(I+1))      OMTX = IF16 .GE. 19 .AND. IF16 .LE. 20      CFIT = IF16 .GE. 16 .AND. IF16 .LE. 20      MPRN = .TRUE.      GO TO 5200C 1700 MPRN = .TRUE.      GO TO 5200C 1800 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 1900 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C 2000 RMTX = .NOT. REFER      MPRN = .TRUE.      GO TO 5200C 2500 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 2700 MPRN = .TRUE.      GO TO 5200C 2800 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 3100 MPRN = PMK      GO TO 5200C 3300 MPRN = .TRUE.      GO TO 5200C 3400 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C 3500 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 3700 MPRN = .TRUE.      GO TO 5200C 3800 MPRN = .TRUE.      GO TO 5200C 4100 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 4200 RMTX = .TRUE.      MPRN = .TRUE.      GO TO 5200C 4300 OMTX = RCP .OR. R2P      MPRN = .TRUE.      GO TO 5200C 4500 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C 4600 RMTX = .TRUE.      RSYM = .TRUE.      MPRN = .TRUE.      GO TO 5200C 5200 OMTX = RMTX .OR. OMTX      CFIT = OMTX .OR. CFIT      RETURN      END